from __future__ import annotations
import base64, zlib
from pathlib import Path
import subprocess
PATCH_B64 = ""
patch_path = Path('/tmp/iter33-docs.patch')
patch_path.write_bytes(zlib.decompress(base64.b64decode(PATCH_B64)))
subprocess.run(['git','apply','--check',str(patch_path)], check=True)
subprocess.run(['git','apply',str(patch_path)], check=True)
